PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY, title TEXT NOT NULL, featured_image TEXT, author TEXT, post_date TEXT, content TEXT NOT NULL DEFAULT '', tags TEXT, seo_title TEXT, seo_description TEXT, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published')));
CREATE INDEX IF NOT EXISTS blog_status_date ON blog_posts(status, post_date);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, event_date TEXT NOT NULL, activity TEXT NOT NULL, description TEXT, start_time TEXT, end_time TEXT, image_url TEXT, video_url TEXT, booking_status TEXT, seats TEXT, whatsapp_enabled INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL CHECK(status IN ('draft','published')), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_date_status ON events(event_date,status);
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT, rating INTEGER CHECK(rating BETWEEN 1 AND 5), message TEXT NOT NULL, submitted_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved')));
CREATE INDEX IF NOT EXISTS feedback_submitted ON feedback(submitted_at DESC);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (ip_hash TEXT NOT NULL, bucket INTEGER NOT NULL, hits INTEGER NOT NULL, PRIMARY KEY(ip_hash,bucket));

-- Planned D1 equivalents for the editable Gallery and Creative Combos collections.
CREATE TABLE IF NOT EXISTS gallery_items (id TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS creative_combos (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')), created_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS past_events (id TEXT PRIMARY KEY, date_label TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image_url TEXT, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')), sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS past_events_order ON past_events(status, sort_order, created_at);

INSERT OR IGNORE INTO past_events (id,date_label,title,description,status,sort_order,created_at) VALUES
('past-paper-quilling','Aug 15','Paper Quilling','We didn't do the usual basic paper coils here. Everyone rolled, pinched, and shaped simple paper strips into pieces that honestly surprised all of us. Just a quiet, relaxed day turning everyday sheets into neat art.','published',1,'2026-10-12T00:00:00Z'),
('past-clay-animals','Aug 23','Clay Animals','Messy palms, clay on noses, and lots of giggles. The kids rolled little paws, stuck on tiny tails, and put together their own funny, sweet desk buddies from scratch. Imperfect, totally handmade, and they couldn't stop smiling when showing them off.','published',2,'2026-10-12T00:00:01Z'),
('past-granny-square','Aug 23','Granny Square Mini Bags','Definitely not an old granny hobby! It takes real focus to get into the groove, but sitting in our cozy corner, chatting, and laughing made the hours fly. Next thing you know, everyone was holding their own little stitched bag.','published',3,'2026-10-12T00:00:02Z'),
('past-ganapathi','2 Days','Ganapathi Clay Idol Making','Welcoming Bappa hits different when your hands are full of natural clay. It all started with our little artist Hema molding our very first Pillaiyar with her tiny hands. That one spark turned into a full September celebration. Moms and sons sat together passing clay back and forth, getting properly messy, and crafting 15 sweet handmade Bappas. A huge win and pure blessings.','published',4,'2026-10-12T00:00:03Z'),
('past-oct-weekend','Oct 02 & 03','Clay Animals, Cards, Crochet & Mood Magnets','The studio was packed and happy all weekend. Yarn rolling everywhere, clay dust on tables, and kids making friends across the room without a phone or tablet in sight. Some made cute fridge magnets, some made cards for home, and some just got hooked on looping yarn.','published',5,'2026-10-12T00:00:04Z'),
('past-warli','Oct 05','Warli Painting','Simple white paint on rustic paper. We took a break from the usual routine, slowed right down, and painted classic folk figures, dancers, and trees stroke by stroke.','published',6,'2026-10-12T00:00:05Z'),
('past-letters','Oct 18','Letters & Little Moments','A soft, slow afternoon to sit down with real paper and a pen. In between tea and quiet talks, we wrote down the little thoughts and moments that usually get lost in busy days.','published',7,'2026-10-12T00:00:06Z'),
('past-punch-needling','','Punch Needling','Just the rhythmic thump of the needle and piles of cozy yarn. Watching a plain piece of cloth puff up into soft, fluffy art made everyone want to run their fingers over it.','published',8,'2026-10-12T00:00:07Z'),
('past-monogram-quilling','','Monogram Quilling','Picking an initial and patiently filling it up with swirling coils of paper. It took a lot of quiet patience, but having that personalized piece ready to take home was so satisfying.','published',9,'2026-10-12T00:00:08Z'),
('past-gift-box','','Gift Box Making','Folding, creasing, and glueing sturdy little boxes by hand. A gift feels twice as sweet when the box took just as much heart to make as whatever goes inside.','published',10,'2026-10-12T00:00:09Z'),
('past-texture-art','','Texture Art','Big scoops of paste spread out thick like cake frosting. Total permission to make a mess, drag lines with the palette knife, and play around without worrying about mistakes.','published',11,'2026-10-12T00:00:10Z'),
('past-mood-magnets','','Mood Magnets','Little clay faces to stick on the fridge and tell the family how you're doing today. Plenty of laughs around the room making everything from silly smirks to dramatic sleepy faces.','published',12,'2026-10-12T00:00:11Z');


-- Seed the current Little Stories into the editable blog CMS. Re-running this file is safe.
INSERT OR IGNORE INTO blog_posts (id,title,featured_image,author,post_date,content,status,created_at) VALUES
('story-pista-army','The Pista Army',NULL,'Ella’s Nook',NULL,'A handful of pistachio shells that might otherwise have been thrown away became a little army of hand-painted characters.\n\nThere were tiny faces, colourful details and plenty of personality. One of our visitors, a software engineer, found himself painting delicate blush onto a pistachio shell ... not exactly part of his usual day.\n\nSoon, a whole row of silly little faces had found a home on our windowsill.\n\nWho knew leftover shells could have so much character?','published','2026-10-12T00:01:00Z'),
('story-first-stitches','The First Stitches','/assets/gallery/04.jpg','Ella’s Nook',NULL,'Every crochet project begins somewhere.\n\nSometimes, it starts with a ball of yarn, a hook and a few uncertain loops. Slowly, the stitches begin to take shape, and what once felt unfamiliar starts becoming a little more natural.\n\nWe love watching those first attempts turn into something people can proudly call their own.\n\nSmall beginnings deserve a little celebration, too.','published','2026-10-12T00:01:01Z'),
('story-afternoon-table','An Afternoon Around the Table','/assets/gallery/10.jpg','Ella’s Nook',NULL,'Not every visit needs a finished masterpiece.\n\nSometimes, it’s simply about sitting together, trying something new, chatting between steps and enjoying a break from the usual routine.\n\nA shared afternoon at the Nook can be made up of little things ... a new technique, a funny mistake, a surprising idea or a creation that turns out differently from what you imagined.\n\nAnd often, that’s what makes it memorable.','published','2026-10-12T00:01:02Z');
